import AppKit
import Testing
@testable import Stickermine

/// The app icon (spec section 16): ten classic slices on the 824/1024 grid,
/// generated by design/make-icon.sh and committed.
struct AppIconTests {
    static let folder = "Assets.xcassets/AppIcon.appiconset/"

    struct Slice: Decodable {
        let filename: String
        let idiom: String
        let scale: String
        let size: String
    }

    struct Contents: Decodable {
        let images: [Slice]
    }

    private func slices() throws -> [Slice] {
        let data = try Data(contentsOf: SourceFiles.appRoot.appendingPathComponent(Self.folder + "Contents.json"))
        return try JSONDecoder().decode(Contents.self, from: data).images
    }

    @Test func theSetHasTheTenMacSlicesAtTheirPixelSizes() throws {
        let slices = try slices()
        #expect(slices.count == 10)
        #expect(Set(slices.map { "\($0.size)@\($0.scale)" }) == Set(["16x16", "32x32", "128x128", "256x256", "512x512"]
            .flatMap { ["\($0)@1x", "\($0)@2x"] }))
        for slice in slices {
            #expect(slice.idiom == "mac")
            let points = Int(slice.size.split(separator: "x")[0])!
            let pixels = points * (slice.scale == "2x" ? 2 : 1)
            let url = SourceFiles.appRoot.appendingPathComponent(Self.folder + slice.filename)
            let info = try #require(MasterImage.fileInfo(at: url), "\(slice.filename) is missing or unreadable")
            #expect(info.pixelWidth == pixels && info.pixelHeight == pixels, "\(slice.filename)")
        }
    }

    @Test func theTileSitsOnThe824Grid() throws {
        let url = SourceFiles.appRoot.appendingPathComponent(Self.folder + "icon_512x512@2x.png")
        let icon = try #require(MasterImage.image(at: url))
        #expect(icon.width == 1024)
        // 100 px of transparent margin on every side, then the blue tile.
        for (x, y) in [(50, 512), (512, 50), (973, 512), (512, 973), (5, 5)] {
            #expect(TestImages.rgba(of: icon, x: x, y: y)[3] == 0, "(\(x), \(y)) should be transparent")
        }
        let tile = TestImages.rgba(of: icon, x: 150, y: 512)
        #expect(tile[3] == 255)
        #expect(abs(Int(tile[0]) - 0x3D) <= 4 && abs(Int(tile[1]) - 0x4B) <= 4 && abs(Int(tile[2]) - 0xE0) <= 4)
        #expect(TestImages.rgba(of: icon, x: 512, y: 512)[3] == 255)
    }

    @Test func theProjectBuildsTheIconAndTheScriptIsCommitted() throws {
        let project = try String(contentsOf: SourceFiles.repoRoot.appendingPathComponent("Stickermine.xcodeproj/project.pbxproj"),
                                 encoding: .utf8)
        #expect(project.components(separatedBy: "ASSETCATALOG_COMPILER_APPICON_NAME = AppIcon;").count - 1 == 2)
        let script = SourceFiles.repoRoot.appendingPathComponent("design/make-icon.sh")
        #expect(FileManager.default.isExecutableFile(atPath: script.path))
        let text = try String(contentsOf: script, encoding: .utf8)
        #expect(text.contains("qlmanage -t -s 1024"))
        #expect(text.contains("sips -z"))
        #expect(text.contains("design/icon-pickaxe.svg"))
    }

    @Test func theBuiltAppCarriesTheIcon() {
        let info = Bundle.main.infoDictionary ?? [:]
        #expect(info["CFBundleIconFile"] as? String == "AppIcon" || info["CFBundleIconName"] as? String == "AppIcon")
    }
}
